import 'package:flutter/material.dart';
import '../../services/auth_service.dart';
class RegisterScreen extends StatefulWidget { const RegisterScreen({super.key}); @override State<RegisterScreen> createState()=>_RegisterScreenState(); }
class _RegisterScreenState extends State<RegisterScreen>{ final name=TextEditingController(),email=TextEditingController(),password=TextEditingController(); String role='customer'; bool loading=false;
Future<void> submit() async { setState(()=>loading=true); try { await AuthService.instance.register(name:name.text,email:email.text,password:password.text,role:role); if(mounted)Navigator.pop(context); } catch(e){ if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('ثبت ناکام شو: ${e.toString()}')));} finally{if(mounted)setState(()=>loading=false);} }
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('حساب جوړول')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'نوم')),TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),DropdownButtonFormField<String>(value:role,items:const[DropdownMenuItem(value:'customer',child:Text('Customer')),DropdownMenuItem(value:'seller',child:Text('Seller'))],onChanged:(v)=>setState(()=>role=v!),decoration:const InputDecoration(labelText:'حساب ډول')),const SizedBox(height:20),FilledButton(onPressed:loading?null:submit,child:Text(loading?'مهرباني...':'ثبت کول'))])); }
